// CreateRulebookByName creates object in the database without hashing the name.
// Use it directly ONLY when objToCreate.Name is hashed name of the object.
func (group *ConfigSaurientV1) CreateRulebookByName(ctx context.Context,
	objToCreate *baseconfigsaurientiov1.Rulebook) (*ConfigRulebook, error) {
	logger.Debugf("[CreateRulebookByName] Received objToCreate: %s", objToCreate.GetName())
	if objToCreate.GetLabels() == nil {
		objToCreate.Labels = make(map[string]string)
	}
	if _, ok := objToCreate.Labels[common.DisplayNameLabel]; !ok {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
	}

	var (
		retryCount int
		result     *baseconfigsaurientiov1.Rulebook
		err        error
	)
	retryCount = 0
	for {
		result, err = group.client.baseClient.
			ConfigSaurientV1().
			Rulebooks().Create(ctx, objToCreate, metav1.CreateOptions{})
		if err != nil {
			logger.Errorf("[CreateRulebookByName] Failed to create Rulebook: %s, error: %+v", objToCreate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToCreate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on create Rulebook: %s", objToCreate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[CreateRulebookByName] context canceled while creating Rulebook: %s", objToCreate.GetName())
				return nil, context.Canceled
			} else if errors.IsAlreadyExists(err) {
				logger.Debugf("[CreateRulebookByName] Rulebook: %s already exists, error: %+v", objToCreate.GetName(), err)
				result, err = group.client.baseClient.ConfigSaurientV1().Rulebooks().Get(ctx, objToCreate.GetName(), metav1.GetOptions{})
				if err != nil {
					logger.Fatalf("[CreateRulebookByName] Unable to Get Rulebook %s after it was flagged as already exists, error: %+v", objToCreate.GetName(), err)
				}
				break
			} else {
				logger.Errorf("[CreateRulebookByName] found unexpected error while creating Rulebook: %s, error: %+v", objToCreate.GetName(), err)
				return nil, err
			}
		} else {
			logger.Debugf("[CreateRulebookByName] Rulebook: %s created successfully", objToCreate.GetName())
			if s, ok := subscriptionMap.Load("rulebooks.config.saurient.io"); ok {
				logger.Debugf("[CreateRulebookByName] Rulebook: %s stored in wr-cache", objToCreate.GetName())
				s.(subscription).WriteCacheObjects.Store(objToCreate.GetName(), result)
			}
			break
		}
	}

	parentName, ok := objToCreate.GetLabels()["configs.config.saurient.io"]
	if !ok {
		parentName = helper.DefaultKey
	}
	parentHashedName := helper.GetHashedName("configs.config.saurient.io", objToCreate.GetLabels(), parentName)

	AddChild("configs.config.saurient.io", parentHashedName, "rulebooks.config.saurient.io", objToCreate.Name)

	logger.Debugf("[CreateRulebookByName] Executed Successfully: %s", objToCreate.GetName())
	return &ConfigRulebook{
		client:   group.client,
		Rulebook: result,
	}, nil
}

