// UpdateInventoryByName updates object stored in the database under the hashedName which is a hash of
// display name and parents names.
func (group *InventorySaurientV1) UpdateInventoryByName(ctx context.Context,
	objToUpdate *baseinventorysaurientiov1.Inventory) (*InventoryInventory, error) {
	logger.Debugf("[UpdateInventoryByName] Received objToUpdate: %s", objToUpdate.GetName())
	if objToUpdate.Labels[common.DisplayNameLabel] != helper.DefaultKey {
		return nil, NewSingletonNameError(objToUpdate.Labels[common.DisplayNameLabel])
	}

	var patch Patch

	if objToUpdate.Annotations != nil || objToUpdate.Labels != nil {
		current, err := group.client.Inventory().GetInventoryByName(ctx, objToUpdate.Name)
		if err != nil {
			return nil, err
		}

		if objToUpdate.Annotations != nil {
			if current.Annotations[ownershipAnnotation] != "" {
				objToUpdate.Annotations[ownershipAnnotation] = current.Annotations[ownershipAnnotation]
			}
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/annotations",
				Value: objToUpdate.Annotations,
			})
		}

		if objToUpdate.Labels != nil {
			parentsList := helper.GetCRDParentsMap()["inventories.inventory.saurient.io"]
			for _, k := range parentsList {
				objToUpdate.Labels[k] = current.Labels[k]
			}
			objToUpdate.Labels[common.IsNameHashedLabel] = current.Labels[common.IsNameHashedLabel]
			objToUpdate.Labels[common.DisplayNameLabel] = current.Labels[common.DisplayNameLabel]
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/labels",
				Value: objToUpdate.Labels,
			})
		}
		patch = append(patch, PatchOp{
			Op:    "replace",
			Path:  "/metadata/finalizers",
			Value: objToUpdate.Finalizers,
		})
	}

	marshaled, err := patch.Marshal()
	if err != nil {
		return nil, err
	}

	var (
		result *baseinventorysaurientiov1.Inventory
	)
	newCtx := context.TODO()
	retryCount := 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Inventories().Patch(newCtx, objToUpdate.GetName(), types.JSONPatchType, marshaled, metav1.PatchOptions{}, "")
		if err != nil {
			logger.Errorf("[UpdateInventoryByName] Failed to patch Inventory %s with error: %+v", objToUpdate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToUpdate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on patching: %s", objToUpdate.GetName())
					logger.Debugf("Trigger Inventory Delete: %s", objToUpdate.GetName())
					delErr := group.DeleteInventoryByName(newCtx, objToUpdate.GetName())
					if delErr != nil {
						logger.Debugf("Error occur while deleting Inventory: %s", objToUpdate.GetName())
						return nil, delErr
					}
					logger.Debugf("Inventory deleted: %s", objToUpdate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[UpdateInventoryByName]: context canceled: %s", objToUpdate.GetName())
				return nil, context.Canceled
			} else {
				logger.Errorf("[UpdateInventoryByName] Object: %s unexpected error: %+v", objToUpdate.GetName(), err)
				logger.Debugf("Trigger Inventory Delete: %s", objToUpdate.GetName())
				delErr := group.DeleteInventoryByName(newCtx, objToUpdate.GetName())
				if delErr != nil {
					logger.Debugf("Error occur while deleting Inventory: %+v", objToUpdate.GetName())
					return nil, delErr
				}
				logger.Debugf("Inventory Deleted: %s", objToUpdate.GetName())
				return nil, err
			}
		} else {
			logger.Debugf("[UpdateInventoryByName] Patch Inventory Success :%s", objToUpdate.GetName())
			if s, ok := subscriptionMap.Load("inventories.inventory.saurient.io"); ok {
				logger.Debugf("[UpdateInventoryByName] %s stored in wr-cache", objToUpdate.GetName())
				s.(subscription).WriteCacheObjects.Store(objToUpdate.GetName(), result)
			}
			break
		}
	}
	logger.Debugf("[UpdateInventoryByName] Executed Successfully %s", objToUpdate.GetName())
	return &InventoryInventory{
		client:    group.client,
		Inventory: result,
	}, nil
}

