// AddAgencies calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (obj *InventoryInventory) AddAgencies(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.ACVAgency) (result *InventoryACVAgency, err error) {
	logger.Debugf("[AddAgencies] Received objToAdd: %s", objToCreate.GetName())
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for _, v := range helper.GetCRDParentsMap()["inventories.inventory.saurient.io"] {
		objToCreate.Labels[v] = obj.Labels[v]
	}
	objToCreate.Labels["inventories.inventory.saurient.io"] = obj.DisplayName()
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName(objToCreate.CRDName(), objToCreate.Labels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	result, err = obj.client.Inventory().CreateACVAgencyByName(ctx, objToCreate)
	logger.Debugf("[AddAgencies] ACVAgency created successfully: %s", objToCreate.GetName())
	updatedObj, getErr := obj.client.Inventory().GetInventoryByName(ctx, obj.GetName())
	if getErr == nil {
		obj.Inventory = updatedObj.Inventory
	}
	logger.Debugf("[AddAgencies] Executed Successfully: %s", objToCreate.GetName())
	return
}

