func (n *InventoryTenantProducts) Next(ctx context.Context) (*InventoryProduct, error) {
	for index, child := range n.Products {
		logger.Debugf("[InventoryTenantProducts Next] Get next Products with name %s", child.Name)
		obj, err := n.client.Inventory().GetProductByName(ctx, child.Name)
		if err == nil {
			if index == len(n.Products)-1 {
				n.Products = nil
			} else {
				n.Products = n.Products[index+1:]
			}
			return obj, nil
		} else if errors.IsNotFound(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, nil
}

