func (n *InventoryFacilityMeters) Next(ctx context.Context) (*InventoryMeter, error) {
	for index, child := range n.Meters {
		logger.Debugf("[InventoryFacilityMeters Next] Get next Meters with name %s", child.Name)
		obj, err := n.client.Inventory().GetMeterByName(ctx, child.Name)
		if err == nil {
			if index == len(n.Meters)-1 {
				n.Meters = nil
			} else {
				n.Meters = n.Meters[index+1:]
			}
			return obj, nil
		} else if errors.IsNotFound(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, nil
}

