// GetMeters returns child which has given displayName
func (obj *InventoryFacility) GetMeters(ctx context.Context,
	displayName string) (result *InventoryMeter, err error) {

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["facilities.inventory.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("meters.inventory.saurient.io", parentLabels, displayName)
	logger.Debugf("[GetMeters] in InventoryFacility with name %s, displayName %s, parentLabels %#v", childHashName, displayName, parentLabels)
	if IsChildExists("facilities.inventory.saurient.io", obj.Name, "meters.inventory.saurient.io", childHashName) == false {
		logger.Debugf("[GetMeters] ChildNotFound Meters with name %s, displayName %s ", childHashName, displayName)
		return nil, NewChildNotFound(obj.DisplayName(), "Inventory.Facility", "Meters", displayName)
	}

	logger.Debugf("[GetMeters] invoke GetMeterByName name %s, displayName %s", childHashName, displayName)
	result, err = obj.client.Inventory().GetMeterByName(ctx, childHashName)
	return
}

// AddMeters calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (obj *InventoryFacility) AddMeters(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.Meter) (result *InventoryMeter, err error) {
	logger.Debugf("[AddMeters] Received objToAdd: %s", objToCreate.GetName())
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for _, v := range helper.GetCRDParentsMap()["facilities.inventory.saurient.io"] {
		objToCreate.Labels[v] = obj.Labels[v]
	}
	objToCreate.Labels["facilities.inventory.saurient.io"] = obj.DisplayName()
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName(objToCreate.CRDName(), objToCreate.Labels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	result, err = obj.client.Inventory().CreateMeterByName(ctx, objToCreate)
	logger.Debugf("[AddMeters] Meter created successfully: %s", objToCreate.GetName())
	updatedObj, getErr := obj.client.Inventory().GetFacilityByName(ctx, obj.GetName())
	if getErr == nil {
		obj.Facility = updatedObj.Facility
	}
	logger.Debugf("[AddMeters] Executed Successfully: %s", objToCreate.GetName())
	return
}

// DeleteMeters calculates hashed name of the child to delete based on displayName
// and parents names and deletes it.

func (obj *InventoryFacility) DeleteMeters(ctx context.Context, displayName string) (err error) {
	logger.Debugf("[ DeleteMeters] Received for Meter object: %s to delete", displayName)

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["facilities.inventory.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("meters.inventory.saurient.io", parentLabels, displayName)
	if IsChildExists("facilities.inventory.saurient.io", obj.Name, "meters.inventory.saurient.io", childHashName) == false {
		return NewChildNotFound(obj.DisplayName(), "Inventory.Facility", "Meters", displayName)
	}

	err = obj.client.Inventory().DeleteMeterByName(ctx, childHashName)
	if err != nil {
		return err
	}
	logger.Debugf("[ DeleteMeters] Meter object: %s deleted successfully", displayName)
	updatedObj, err := obj.client.Inventory().GetFacilityByName(ctx, obj.GetName())
	if err == nil {
		obj.Facility = updatedObj.Facility
	}
	return
}

