// UpdateMeterByName updates object stored in the database under the hashedName which is a hash of
// display name and parents names.
func (group *InventorySaurientV1) UpdateMeterByName(ctx context.Context,
	objToUpdate *baseinventorysaurientiov1.Meter) (*InventoryMeter, error) {
	logger.Debugf("[UpdateMeterByName] Received objToUpdate: %s", objToUpdate.GetName())

	var patch Patch

	if objToUpdate.Annotations != nil || objToUpdate.Labels != nil {
		current, err := group.client.Inventory().GetMeterByName(ctx, objToUpdate.Name)
		if err != nil {
			return nil, err
		}

		if objToUpdate.Annotations != nil {
			if current.Annotations[ownershipAnnotation] != "" {
				objToUpdate.Annotations[ownershipAnnotation] = current.Annotations[ownershipAnnotation]
			}
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/annotations",
				Value: objToUpdate.Annotations,
			})
		}

		if objToUpdate.Labels != nil {
			parentsList := helper.GetCRDParentsMap()["meters.inventory.saurient.io"]
			for _, k := range parentsList {
				objToUpdate.Labels[k] = current.Labels[k]
			}
			objToUpdate.Labels[common.IsNameHashedLabel] = current.Labels[common.IsNameHashedLabel]
			objToUpdate.Labels[common.DisplayNameLabel] = current.Labels[common.DisplayNameLabel]
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/labels",
				Value: objToUpdate.Labels,
			})
		}
		patch = append(patch, PatchOp{
			Op:    "replace",
			Path:  "/metadata/finalizers",
			Value: objToUpdate.Finalizers,
		})
	}

	var rt reflect.Type

	rt = reflect.TypeOf(objToUpdate.Spec.MeterID)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.MeterID).IsNil() {
			patchValueMeterID := objToUpdate.Spec.MeterID
			patchOpMeterID := PatchOp{
				Op:    "replace",
				Path:  "/spec/meterID",
				Value: patchValueMeterID,
			}
			patch = append(patch, patchOpMeterID)
		}
	} else {
		patchValueMeterID := objToUpdate.Spec.MeterID
		patchOpMeterID := PatchOp{
			Op:    "replace",
			Path:  "/spec/meterID",
			Value: patchValueMeterID,
		}
		patch = append(patch, patchOpMeterID)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.MeterType)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.MeterType).IsNil() {
			patchValueMeterType := objToUpdate.Spec.MeterType
			patchOpMeterType := PatchOp{
				Op:    "replace",
				Path:  "/spec/meterType",
				Value: patchValueMeterType,
			}
			patch = append(patch, patchOpMeterType)
		}
	} else {
		patchValueMeterType := objToUpdate.Spec.MeterType
		patchOpMeterType := PatchOp{
			Op:    "replace",
			Path:  "/spec/meterType",
			Value: patchValueMeterType,
		}
		patch = append(patch, patchOpMeterType)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.Manufacturer)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.Manufacturer).IsNil() {
			patchValueManufacturer := objToUpdate.Spec.Manufacturer
			patchOpManufacturer := PatchOp{
				Op:    "replace",
				Path:  "/spec/manufacturer",
				Value: patchValueManufacturer,
			}
			patch = append(patch, patchOpManufacturer)
		}
	} else {
		patchValueManufacturer := objToUpdate.Spec.Manufacturer
		patchOpManufacturer := PatchOp{
			Op:    "replace",
			Path:  "/spec/manufacturer",
			Value: patchValueManufacturer,
		}
		patch = append(patch, patchOpManufacturer)
	}

	marshaled, err := patch.Marshal()
	if err != nil {
		return nil, err
	}

	var (
		result *baseinventorysaurientiov1.Meter
	)
	newCtx := context.TODO()
	retryCount := 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Meters().Patch(newCtx, objToUpdate.GetName(), types.JSONPatchType, marshaled, metav1.PatchOptions{}, "")
		if err != nil {
			logger.Errorf("[UpdateMeterByName] Failed to patch Meter %s with error: %+v", objToUpdate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToUpdate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on patching: %s", objToUpdate.GetName())
					logger.Debugf("Trigger Meter Delete: %s", objToUpdate.GetName())
					delErr := group.DeleteMeterByName(newCtx, objToUpdate.GetName())
					if delErr != nil {
						logger.Debugf("Error occur while deleting Meter: %s", objToUpdate.GetName())
						return nil, delErr
					}
					logger.Debugf("Meter deleted: %s", objToUpdate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[UpdateMeterByName]: context canceled: %s", objToUpdate.GetName())
				return nil, context.Canceled
			} else {
				logger.Errorf("[UpdateMeterByName] Object: %s unexpected error: %+v", objToUpdate.GetName(), err)
				logger.Debugf("Trigger Meter Delete: %s", objToUpdate.GetName())
				delErr := group.DeleteMeterByName(newCtx, objToUpdate.GetName())
				if delErr != nil {
					logger.Debugf("Error occur while deleting Meter: %+v", objToUpdate.GetName())
					return nil, delErr
				}
				logger.Debugf("Meter Deleted: %s", objToUpdate.GetName())
				return nil, err
			}
		} else {
			logger.Debugf("[UpdateMeterByName] Patch Meter Success :%s", objToUpdate.GetName())
			if s, ok := subscriptionMap.Load("meters.inventory.saurient.io"); ok {
				logger.Debugf("[UpdateMeterByName] %s stored in wr-cache", objToUpdate.GetName())
				s.(subscription).WriteCacheObjects.Store(objToUpdate.GetName(), result)
			}
			break
		}
	}
	logger.Debugf("[UpdateMeterByName] Executed Successfully %s", objToUpdate.GetName())
	return &InventoryMeter{
		client: group.client,
		Meter:  result,
	}, nil
}

