// GetDeclarations returns child which has given displayName
func (obj *InventorySupplier) GetDeclarations(ctx context.Context,
	displayName string) (result *InventoryDeclaration, err error) {

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["suppliers.inventory.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("declarations.inventory.saurient.io", parentLabels, displayName)
	logger.Debugf("[GetDeclarations] in InventorySupplier with name %s, displayName %s, parentLabels %#v", childHashName, displayName, parentLabels)
	if IsChildExists("suppliers.inventory.saurient.io", obj.Name, "declarations.inventory.saurient.io", childHashName) == false {
		logger.Debugf("[GetDeclarations] ChildNotFound Declarations with name %s, displayName %s ", childHashName, displayName)
		return nil, NewChildNotFound(obj.DisplayName(), "Inventory.Supplier", "Declarations", displayName)
	}

	logger.Debugf("[GetDeclarations] invoke GetDeclarationByName name %s, displayName %s", childHashName, displayName)
	result, err = obj.client.Inventory().GetDeclarationByName(ctx, childHashName)
	return
}

// AddDeclarations calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (obj *InventorySupplier) AddDeclarations(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.Declaration) (result *InventoryDeclaration, err error) {
	logger.Debugf("[AddDeclarations] Received objToAdd: %s", objToCreate.GetName())
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for _, v := range helper.GetCRDParentsMap()["suppliers.inventory.saurient.io"] {
		objToCreate.Labels[v] = obj.Labels[v]
	}
	objToCreate.Labels["suppliers.inventory.saurient.io"] = obj.DisplayName()
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName(objToCreate.CRDName(), objToCreate.Labels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	result, err = obj.client.Inventory().CreateDeclarationByName(ctx, objToCreate)
	logger.Debugf("[AddDeclarations] Declaration created successfully: %s", objToCreate.GetName())
	updatedObj, getErr := obj.client.Inventory().GetSupplierByName(ctx, obj.GetName())
	if getErr == nil {
		obj.Supplier = updatedObj.Supplier
	}
	logger.Debugf("[AddDeclarations] Executed Successfully: %s", objToCreate.GetName())
	return
}

// DeleteDeclarations calculates hashed name of the child to delete based on displayName
// and parents names and deletes it.

func (obj *InventorySupplier) DeleteDeclarations(ctx context.Context, displayName string) (err error) {
	logger.Debugf("[ DeleteDeclarations] Received for Declaration object: %s to delete", displayName)

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["suppliers.inventory.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("declarations.inventory.saurient.io", parentLabels, displayName)
	if IsChildExists("suppliers.inventory.saurient.io", obj.Name, "declarations.inventory.saurient.io", childHashName) == false {
		return NewChildNotFound(obj.DisplayName(), "Inventory.Supplier", "Declarations", displayName)
	}

	err = obj.client.Inventory().DeleteDeclarationByName(ctx, childHashName)
	if err != nil {
		return err
	}
	logger.Debugf("[ DeleteDeclarations] Declaration object: %s deleted successfully", displayName)
	updatedObj, err := obj.client.Inventory().GetSupplierByName(ctx, obj.GetName())
	if err == nil {
		obj.Supplier = updatedObj.Supplier
	}
	return
}

