// AddPassports calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (obj *RuntimeRuntime) AddPassports(ctx context.Context,
	objToCreate *baseruntimesaurientiov1.CarbonPassport) (result *RuntimeCarbonPassport, err error) {
	logger.Debugf("[AddPassports] Received objToAdd: %s", objToCreate.GetName())
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for _, v := range helper.GetCRDParentsMap()["runtimes.runtime.saurient.io"] {
		objToCreate.Labels[v] = obj.Labels[v]
	}
	objToCreate.Labels["runtimes.runtime.saurient.io"] = obj.DisplayName()
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName(objToCreate.CRDName(), objToCreate.Labels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	result, err = obj.client.Runtime().CreateCarbonPassportByName(ctx, objToCreate)
	logger.Debugf("[AddPassports] CarbonPassport created successfully: %s", objToCreate.GetName())
	updatedObj, getErr := obj.client.Runtime().GetRuntimeByName(ctx, obj.GetName())
	if getErr == nil {
		obj.Runtime = updatedObj.Runtime
	}
	logger.Debugf("[AddPassports] Executed Successfully: %s", objToCreate.GetName())
	return
}

// DeletePassports calculates hashed name of the child to delete based on displayName
// and parents names and deletes it.

func (obj *RuntimeRuntime) DeletePassports(ctx context.Context, displayName string) (err error) {
	logger.Debugf("[ DeletePassports] Received for CarbonPassport object: %s to delete", displayName)

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["runtimes.runtime.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("carbonpassports.runtime.saurient.io", parentLabels, displayName)
	if IsChildExists("runtimes.runtime.saurient.io", obj.Name, "carbonpassports.runtime.saurient.io", childHashName) == false {
		return NewChildNotFound(obj.DisplayName(), "Runtime.Runtime", "Passports", displayName)
	}

	err = obj.client.Runtime().DeleteCarbonPassportByName(ctx, childHashName)
	if err != nil {
		return err
	}
	logger.Debugf("[ DeletePassports] CarbonPassport object: %s deleted successfully", displayName)
	updatedObj, err := obj.client.Runtime().GetRuntimeByName(ctx, obj.GetName())
	if err == nil {
		obj.Runtime = updatedObj.Runtime
	}
	return
}

