func (n *RuntimeCarbonPassportAuditRecords) Next(ctx context.Context) (*RuntimeAuditRecord, error) {
	for index, child := range n.AuditRecords {
		logger.Debugf("[RuntimeCarbonPassportAuditRecords Next] Get next AuditRecords with name %s", child.Name)
		obj, err := n.client.Runtime().GetAuditRecordByName(ctx, child.Name)
		if err == nil {
			if index == len(n.AuditRecords)-1 {
				n.AuditRecords = nil
			} else {
				n.AuditRecords = n.AuditRecords[index+1:]
			}
			return obj, nil
		} else if errors.IsNotFound(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, nil
}

