// GetAuditRecords returns child which has given displayName
func (obj *RuntimeCarbonPassport) GetAuditRecords(ctx context.Context,
	displayName string) (result *RuntimeAuditRecord, err error) {

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["carbonpassports.runtime.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("auditrecords.runtime.saurient.io", parentLabels, displayName)
	logger.Debugf("[GetAuditRecords] in RuntimeCarbonPassport with name %s, displayName %s, parentLabels %#v", childHashName, displayName, parentLabels)
	if IsChildExists("carbonpassports.runtime.saurient.io", obj.Name, "auditrecords.runtime.saurient.io", childHashName) == false {
		logger.Debugf("[GetAuditRecords] ChildNotFound AuditRecords with name %s, displayName %s ", childHashName, displayName)
		return nil, NewChildNotFound(obj.DisplayName(), "Runtime.CarbonPassport", "AuditRecords", displayName)
	}

	logger.Debugf("[GetAuditRecords] invoke GetAuditRecordByName name %s, displayName %s", childHashName, displayName)
	result, err = obj.client.Runtime().GetAuditRecordByName(ctx, childHashName)
	return
}

// AddAuditRecords calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (obj *RuntimeCarbonPassport) AddAuditRecords(ctx context.Context,
	objToCreate *baseruntimesaurientiov1.AuditRecord) (result *RuntimeAuditRecord, err error) {
	logger.Debugf("[AddAuditRecords] Received objToAdd: %s", objToCreate.GetName())
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for _, v := range helper.GetCRDParentsMap()["carbonpassports.runtime.saurient.io"] {
		objToCreate.Labels[v] = obj.Labels[v]
	}
	objToCreate.Labels["carbonpassports.runtime.saurient.io"] = obj.DisplayName()
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName(objToCreate.CRDName(), objToCreate.Labels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	result, err = obj.client.Runtime().CreateAuditRecordByName(ctx, objToCreate)
	logger.Debugf("[AddAuditRecords] AuditRecord created successfully: %s", objToCreate.GetName())
	updatedObj, getErr := obj.client.Runtime().GetCarbonPassportByName(ctx, obj.GetName())
	if getErr == nil {
		obj.CarbonPassport = updatedObj.CarbonPassport
	}
	logger.Debugf("[AddAuditRecords] Executed Successfully: %s", objToCreate.GetName())
	return
}

// DeleteAuditRecords calculates hashed name of the child to delete based on displayName
// and parents names and deletes it.

func (obj *RuntimeCarbonPassport) DeleteAuditRecords(ctx context.Context, displayName string) (err error) {
	logger.Debugf("[ DeleteAuditRecords] Received for AuditRecord object: %s to delete", displayName)

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["carbonpassports.runtime.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("auditrecords.runtime.saurient.io", parentLabels, displayName)
	if IsChildExists("carbonpassports.runtime.saurient.io", obj.Name, "auditrecords.runtime.saurient.io", childHashName) == false {
		return NewChildNotFound(obj.DisplayName(), "Runtime.CarbonPassport", "AuditRecords", displayName)
	}

	err = obj.client.Runtime().DeleteAuditRecordByName(ctx, childHashName)
	if err != nil {
		return err
	}
	logger.Debugf("[ DeleteAuditRecords] AuditRecord object: %s deleted successfully", displayName)
	updatedObj, err := obj.client.Runtime().GetCarbonPassportByName(ctx, obj.GetName())
	if err == nil {
		obj.CarbonPassport = updatedObj.CarbonPassport
	}
	return
}

